+/**
+ * ThreadedNotificationService — stateful service that composes the Slack client,
+ * the Redis thread store, and the message formatters to provide scope-separated
+ * Slack threading for feature and task notifications.
+ *
+ * All public methods emit structured events and never throw in a way that would
+ * block workflow progression.
+ */
+
+import type { SlackWebApiClient } from "../slack/slack-web-api-client.js";
+import type { NotificationThreadStorePort } from "../ports/notification-thread-store.port.js";
+import type {
+  FeatureTrigger,
+  FeatureContext,
+  TaskTrigger,
+  TaskContext,
+} from "./notification.types.js";
+import {
+  formatFeatureTopLevel,
+  formatFeatureReply,
+  extractFeatureChangedFields,
+} from "./feature-formatter.js";
+import {
+  formatTaskTopLevel,
+  formatTaskReply,
+  extractTaskChangedFields,
+} from "./task-formatter.js";
+
+export interface NotificationServiceDeps {
+  slack: SlackWebApiClient | null;
+  store: NotificationThreadStorePort | null;
+  workspaceId: string;
+  emit: (event: NotificationEvent) => void;
+}
+
+// ── Structured event types ─────────────────────────────────────────────────────
+
+export type NotificationEvent =
+  | { type: "feature_slack_thread_created"; featureId: string; threadTs: string }
+  | { type: "feature_slack_thread_updated"; featureId: string; threadTs: string }
+  | { type: "feature_slack_reply_posted"; featureId: string; threadTs: string }
+  | { type: "feature_slack_thread_deleted"; featureId: string }
+  | { type: "feature_slack_thread_delete_failed"; featureId: string; reason: string }
+  | { type: "task_slack_thread_created"; featureId: string; taskId: string; threadTs: string }
+  | { type: "task_slack_thread_updated"; featureId: string; taskId: string; threadTs: string }
+  | { type: "task_slack_reply_posted"; featureId: string; taskId: string; threadTs: string }
+  | { type: "task_slack_thread_deleted"; featureId: string; taskId: string }
+  | { type: "task_slack_thread_delete_failed"; featureId: string; taskId: string; reason: string }
+  | { type: "slack_notification_skipped"; reason: string }
+  | { type: "slack_notification_failed"; reason: string }
+  | { type: "redis_operation_failed"; operation: string; reason: string };
+
+export class ThreadedNotificationService {
+  constructor(private readonly deps: NotificationServiceDeps) {}
+
+  private get configured(): boolean {
+    return this.deps.slack !== null && this.deps.store !== null;
+  }
+
+  // ── Feature thread ──────────────────────────────────────────────────────────
+
+  /**
+   * Ensure a feature-level Slack thread exists.
+   * - If the Redis key already exists, reuse it.
+   * - If absent and Slack+Redis configured, post the first message and store the ts.
+   */
+  async ensureFeatureThread(
+    featureId: string,
+    context: FeatureContext,
+  ): Promise<string | null> {
+    if (!this.configured) {
+      this.deps.emit({ type: "slack_notification_skipped", reason: "slack_not_configured" });
+      return null;
+    }
+
+    const store = this.deps.store!;
+    const slack = this.deps.slack!;
+
+    let threadTs: string | null;
+    try {
+      threadTs = await store.getFeatureThread(this.deps.workspaceId, featureId);
+    } catch (err) {
+      this.deps.emit({
+        type: "redis_operation_failed",
+        operation: "getFeatureThread",
+        reason: String(err),
+      });
+      return null;
+    }
+
+    if (threadTs) {
+      return threadTs;
+    }
+
+    // Create the feature thread
+    const text = formatFeatureTopLevel(context);
+    let result: { ts: string };
+    try {
+      result = await slack.postMessage(text);
+    } catch (err) {
+      this.deps.emit({
+        type: "slack_notification_failed",
+        reason: `chat.postMessage for feature thread: ${String(err)}`,
+      });
+      return null;
+    }
+
+    try {
+      await store.setFeatureThread(this.deps.workspaceId, featureId, result.ts);
+    } catch (err) {
+      this.deps.emit({
+        type: "redis_operation_failed",
+        operation: "setFeatureThread",
+        reason: String(err),
+      });
+      // Return the ts anyway — message was posted, just not stored
+    }
+
+    this.deps.emit({
+      type: "feature_slack_thread_created",
+      featureId,
+      threadTs: result.ts,
+    });
+
+    return result.ts;
+  }
+
+  /**
+   * Ensure a task-level Slack thread exists.
+   * - If the Redis key already exists, reuse it.
+   * - If absent and Slack+Redis configured, post the first task message and store the ts.
+   */

