+  | { type: "feature_slack_thread_created"; featureId: string; threadTs: string }
+  | { type: "feature_slack_thread_updated"; featureId: string; threadTs: string }
+  | { type: "feature_slack_reply_posted"; featureId: string; threadTs: string }
