1	/**
2	 * Feature message formatters for Slack thread notifications.
3	 *
4	 * Pure functions — no I/O, no Slack or Redis imports.
5	 * Used for both chat.postMessage (create) and chat.update (in-place update).
6	 */
7	
8	import type { FeatureContext, FeatureChangedFields, FeatureTrigger } from "./notification.types.js";
9	import { formatStatusLine } from "./status-icon.js";
10	
11	/**
12	 * Format the top-level feature message text.
13	 *
14	 * Used for:
15	 * - `feature_start`: creates the top-level feature message
16	 * - All subsequent triggers: updates the top-level message in place via chat.update
17	 *
18	 * Absent or irrelevant fields are omitted — no blank lines.
19	 */
20	export function formatFeatureTopLevel(context: FeatureContext): string {
21	  const lines: string[] = [];
22	
23	  lines.push(`Feature: ${context.title}`);
24	  lines.push(formatStatusLine(context.status));
25	
26	  if (context.nextAction) {
27	    lines.push(`Next action: ${context.nextAction}`);
28	  }
29	  if (context.blockedReason) {
30	    lines.push(`Blocked: ${context.blockedReason}`);
31	  }
32	  if (context.handoff) {
33	    lines.push(`Handoff: ${context.handoff}`);
34	  }
35	  if (context.featurePr) {
36	    lines.push(`PR: ${context.featurePr}`);
37	  }
38	
39	  lines.push(`Tasks: ${context.totalTaskCount} total`);
40	
41	  return lines.join("\n");
42	}
43	
44	/**
45	 * Format a feature thread reply message.
46	 *
47	 * Contains only the fields that changed for this event, prefixed with the
48	 * event type. Provides the audit trail alongside the always-current top-level.
49	 *
50	 * Absent changed fields are omitted.
51	 */
52	export function formatFeatureReply(
53	  trigger: FeatureTrigger,
54	  changed: FeatureChangedFields,
55	): string {
56	  const lines: string[] = [];
57	
58	  lines.push(`Type: ${trigger}`);
59	
60	  if (changed.status !== undefined) {
61	    lines.push(formatStatusLine(changed.status));
62	  }
63	  if (changed.handoff !== undefined && changed.handoff !== null) {
64	    lines.push(`Handoff: ${changed.handoff}`);
65	  }
66	  if (changed.featurePr !== undefined && changed.featurePr !== null) {
67	    lines.push(`PR: ${changed.featurePr}`);
68	  }
69	  if (changed.blockedReason !== undefined && changed.blockedReason !== null) {
